        max_size, lattice, position, types, spins, 0 /* tensor_rank */,
        num_atom, 1 /* with_time_reversal */, 0 /* is_axial */, symprec,
        angle_tolerance, mag_symprec);

    free(spin_flips);
    spin_flips = NULL;

    return succeeded;
}

