#include "spglib.h"

int main() {
    double lattice[3][3] = {
        {3.36017962, 0.0, 0.95244787},
        {1.70747655, 3.84457132, 0.37960516},
        {-0.0117898, -0.29501452, 6.4450749},
    };
    double positions[3][3] = {
        {0.0, 0.0, 0.0},
        {0.26737473, 0.2232512, 0.24199933},
        {0.73262527, 0.7767488, 0.75800067},
    };
    int numbers[3] = {0, 1, 1};
    double spins[3] = {0.005, 0.002, 0.002};
    int num_atom = 3;

    int rot[4096][3][3];
    double trans[4096][3];
    int max = 4096;

    int n = spg_get_symmetry(rot, trans, max, lattice, positions, numbers, num_atom, 1e-2, -1.0);
    printf("nonspin sym size at symprec=1e-2: %d\n", n);
    for (int i = 0; i < 10 && i < n; i++) {
        printf("rot %d: [%d %d %d; %d %d %d; %d %d %d] trans %f %f %f\n", i,
               rot[i][0][0], rot[i][0][1], rot[i][0][2],
               rot[i][1][0], rot[i][1][1], rot[i][1][2],
               rot[i][2][0], rot[i][2][1], rot[i][2][2],
               trans[i][0], trans[i][1], trans[i][2]);
    }
    fflush(stdout);

    int equiv[3];
    double prim[3][3];
    int spin_flips[4096];
    int msize = spgms_get_symmetry_with_site_tensors(
        rot, trans, equiv, prim, spin_flips, max, lattice, positions, numbers,
        spins, 0 /* tensor_rank */, num_atom, 1 /* with_time_reversal */,
        0 /* is_axial */, 1e-2, -1.0, -1.0);
    printf("magnetic sym size: %d\n", msize);

    /* try moderate */
    n = spg_get_symmetry(rot, trans, max, lattice, positions, numbers, num_atom, 1e-5, -1.0);
    printf("nonspin sym size at symprec=1e-5: %d\n", n);
    msize = spgms_get_symmetry_with_site_tensors(
        rot, trans, equiv, prim, spin_flips, max, lattice, positions, numbers,
        spins, 0, num_atom, 1, 0, 1e-5, -1.0, -1.0);
