    diff[0..2]
    if (!(is_zero_d3(&cell->tensors[3*i], mag_symprec) &&
          is_zero_d3(&cell->tensors[3*j], mag_symprec)) &&
        !is_zero_d3(diff, mag_symprec)) {
        continue;
    }
}
```

